// Reglas puras para copiar a Code Nodes. Persistencia y bloqueo corresponden a n8n.
const crypto = require('crypto');
class ErrorNegocio extends Error { constructor(status, code, message) { super(message); this.status=status; this.code=code; } }
const fail=(s,c,m)=>{throw new ErrorNegocio(s,c,m)};
const id=()=>crypto.randomUUID();
const email=x=>String(x||'').trim().toLowerCase();
function hashPassword(password, salt=crypto.randomBytes(16).toString('hex')) {
  if(typeof password!=='string'||password.length<12||password.length>128) fail(400,'PASSWORD_INVALIDA','Usa entre 12 y 128 caracteres');
  return {password_salt:salt,password_hash:crypto.scryptSync(password,salt,64).toString('hex')};
}
function verifyPassword(password, u) {
  if (
    typeof password !== 'string' ||
    password.length > 128 ||
    !u?.password_salt ||
    !u?.password_hash
  ) {
    return false;
  }

  const actual = crypto.pbkdf2Sync(
    password,
    u.password_salt,
    120000,
    32,
    'sha256'
  );

  const stored = Buffer.from(u.password_hash, 'hex');

  return (
    stored.length === actual.length &&
    crypto.timingSafeEqual(actual, stored)
  );
}
const publicUser=({usuario_id,nombre,email_normalizado,estado})=>({usuario_id,nombre,email_normalizado,estado});
function createUser(body,users,now=new Date()) {
  const mail=email(body.email),nombre=String(body.nombre||'').trim();
  if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(mail)||!nombre||nombre.length>100) fail(400,'DATOS_INVALIDOS','Revisa nombre y correo');
  if(users.some(u=>u.email_normalizado===mail)) fail(409,'EMAIL_DUPLICADO','El correo ya existe');
  return {usuario_id:id(),nombre,email_normalizado:mail,...hashPassword(body.password),estado:'ACTIVO',fecha_registro:now.toISOString(),fecha_actualizacion:now.toISOString()};
}
function validSession(token,sessions,users,now=new Date()) {
  const s=sessions.find(s=>s.session_token===token&&token);
  if(!s||s.estado!=='ACTIVA'||!Number.isFinite(Date.parse(s.expira_en))||Date.parse(s.expira_en)<=+now) fail(401,'SESION_INVALIDA','Inicia sesión nuevamente');
  const u=users.find(u=>u.usuario_id===s.usuario_id&&u.estado==='ACTIVO');
  if(!u) fail(401,'USUARIO_INACTIVO','Cuenta inactiva');
  return {session:s,user:u};
}
function login(body,users,now=new Date()) {
  const u=users.find(u=>u.email_normalizado===email(body.email));
  if(!u||u.estado!=='ACTIVO'||!verifyPassword(body.password,u)) fail(401,'CREDENCIALES_INVALIDAS','Correo o contraseña inválidos');
  return {session_id:id(),usuario_id:u.usuario_id,session_token:crypto.randomBytes(32).toString('hex'),creada_en:now.toISOString(),expira_en:new Date(+now+8*3600000).toISOString(),estado:'ACTIVA',cerrada_en:'',ultima_validacion:now.toISOString()};
}
const eventTime=e=>Date.parse(`${e.fecha}T${e.hora}:00-05:00`);
const confirmed=(eventId,rows)=>rows.filter(r=>r.evento_id===eventId&&r.estado==='CONFIRMADA').length;
const available=(e,rows)=>Math.max(0,Number(e.capacidad)-confirmed(e.evento_id,rows));
function catalog(events,rows,{evento_id,categoria}={},now=new Date()) {
  return events.filter(e=>e.estado==='PUBLICADO'&&eventTime(e)>+now&&(!evento_id||e.evento_id===evento_id)&&(!categoria||e.categoria===categoria)).map(e=>({...e,cupos_disponibles:available(e,rows)}));
}
function createEnrollment(body,user,links,event,rows,now=new Date()) {
  if(user.estado!=='ACTIVO') fail(401,'USUARIO_INACTIVO','Cuenta inactiva');
  if(!links.some(l=>l.usuario_id===user.usuario_id&&l.estado==='ACTIVA')) fail(409,'TELEGRAM_REQUERIDO','Vincula Telegram primero');
  if(!event) fail(404,'EVENTO_NO_EXISTE','Evento no encontrado');
  if(event.estado!=='PUBLICADO'||!Number.isFinite(eventTime(event))||eventTime(event)<=+now) fail(409,'EVENTO_NO_DISPONIBLE','Evento cerrado o iniciado');
  const old=rows.find(r=>r.usuario_id===user.usuario_id&&r.evento_id===event.evento_id&&['CONFIRMADA','LISTA_ESPERA'].includes(r.estado));
  if(old) return {row:old,created:false};
  const estado=available(event,rows)>0?'CONFIRMADA':'LISTA_ESPERA';
  return {created:true,row:{inscripcion_id:id(),usuario_id:user.usuario_id,evento_id:event.evento_id,estado,fecha_inscripcion:now.toISOString(),fecha_actualizacion:now.toISOString(),nombre_acreditacion:String(body.nombre_acreditacion||user.nombre).slice(0,100),observaciones:String(body.observaciones||'').slice(0,500),origen:'WEB',orden_espera:estado==='LISTA_ESPERA'?Math.max(0,...rows.filter(r=>r.evento_id===event.evento_id).map(r=>Number(r.orden_espera)||0))+1:''}};
}
function cancelEnrollment(row,user,now=new Date()) {
  if(!row||row.usuario_id!==user.usuario_id) fail(404,'INSCRIPCION_NO_EXISTE','Inscripción no encontrada');
  return {...row,estado:'CANCELADA',fecha_actualizacion:now.toISOString()};
}
function promotions(events,rows,users,links,now=new Date()) {
  const promoted=[];
  for(const e of events.filter(e=>e.estado==='PUBLICADO'&&eventTime(e)>+now)) {
    let seats=available(e,rows);
    const waiting=rows.filter(r=>r.evento_id===e.evento_id&&r.estado==='LISTA_ESPERA').sort((a,b)=>Date.parse(a.fecha_inscripcion)-Date.parse(b.fecha_inscripcion)||a.inscripcion_id.localeCompare(b.inscripcion_id));
    for(const r of waiting) {
      if(!seats) break;
      if(!users.some(u=>u.usuario_id===r.usuario_id&&u.estado==='ACTIVO')||!links.some(l=>l.usuario_id===r.usuario_id&&l.estado==='ACTIVA')) continue;
      promoted.push({...r,estado:'CONFIRMADA',fecha_actualizacion:now.toISOString()}); seats--;
    }
  }
  return promoted;
}
function reminderCandidates(events,rows,previous,now=new Date()) {
  const out=[];
  for(const e of events.filter(e=>e.estado==='PUBLICADO'&&eventTime(e)>+now&&eventTime(e)-now<=24*3600000)) {
    for(const r of rows.filter(r=>r.evento_id===e.evento_id&&r.estado==='CONFIRMADA')) {
      const key=`${r.usuario_id}|${e.evento_id}|24H`;
      if(previous.some(p=>p.clave_idempotencia===key&&['ENVIADO','PENDIENTE'].includes(p.estado))) continue;
      out.push({recordatorio_id:id(),usuario_id:r.usuario_id,evento_id:e.evento_id,inscripcion_id:r.inscripcion_id,tipo_recordatorio:'24H',fecha_programada:now.toISOString(),fecha_envio:'',estado:'PENDIENTE',clave_idempotencia:key});
    }
  } return out;
}
function linkingCode(user,now=new Date()) {
  return {codigo_id:id(),usuario_id:user.usuario_id,codigo:crypto.randomBytes(8).toString('hex').toUpperCase(),creado_en:now.toISOString(),expira_en:new Date(+now+10*60000).toISOString(),estado:'PENDIENTE',usado_en:''};
}
function useCode(code,codes,links,users,chatId,username='',now=new Date()) {
  const row=codes.find(c=>c.codigo===code);
  if(!row||row.estado!=='PENDIENTE'||!Number.isFinite(Date.parse(row.expira_en))||Date.parse(row.expira_en)<=+now) fail(409,'CODIGO_INVALIDO','Código usado o vencido');
  if(!users.some(u=>u.usuario_id===row.usuario_id&&u.estado==='ACTIVO')) fail(409,'USUARIO_INACTIVO','Cuenta inactiva');
  if(links.some(l=>String(l.chat_id)===String(chatId)&&l.usuario_id!==row.usuario_id&&l.estado==='ACTIVA')) fail(409,'CHAT_OCUPADO','Este chat ya está vinculado');
  return {code:{...row,estado:'USADO',usado_en:now.toISOString()},link:{vinculacion_id:id(),usuario_id:row.usuario_id,chat_id:String(chatId),telegram_username:username,fecha_vinculacion:now.toISOString(),estado:'ACTIVA'}};
}

const req=$('Entrada Webhook').first().json;
const body=req.body||{};
const token=String(req.headers?.authorization||'').replace(/^Bearer\s+/i,'');
const users=$('Leer usuarios').all().map(i=>i.json).filter(u=>u.usuario_id);
const sessions=$('Leer sesiones').all().map(i=>i.json).filter(s=>s.session_id);
let row=null,result=null,status=200,write=false,audit=null;
try {

const op=body.operacion;
if(op==='LOGIN') {row=login(body,users);write=true;const u=users.find(u=>u.usuario_id===row.usuario_id);result={ok:true,data:{session_token:row.session_token,expira_en:row.expira_en,usuario:publicUser(u)}};}
else if(['VALIDAR','LOGOUT'].includes(op)) {
 const raw=sessions.find(s=>s.session_token===token&&token);
 if(raw&&raw.estado==='ACTIVA'&&(!Number.isFinite(Date.parse(raw.expira_en))||Date.parse(raw.expira_en)<=Date.now())) {row={...raw,estado:'EXPIRADA'};write=true;status=401;result={ok:false,error:{code:'SESION_INVALIDA',message:'Inicia sesión nuevamente'}};}
 else {const {session,user}=validSession(token,sessions,users);row={...session};write=true;
  if(op==='LOGOUT'){row.estado='CERRADA';row.cerrada_en=new Date().toISOString();result={ok:true,data:{cerrada:true}};}
  else {row.ultima_validacion=new Date().toISOString();result={ok:true,data:{usuario:publicUser(user),expira_en:row.expira_en}};}
 }
}else fail(400,'OPERACION_INVALIDA','Operación inválida');

}catch(e){write=false;row=null;status=e.status||500;result={ok:false,error:{code:e.code||'ERROR_INTERNO',message:e.status?e.message:'Error interno'}};}
return [{json:{status,result,write,row,audit}}];
